insert into issues (slug, number, volume, year, cover_image, status, theme, published_date, about_this_volume, editorial_board)
values ($gsj$issue-1$gsj$, 1, 1, 2023, $gsj$https://www.gulfspectrumjournal.com/issue-assets/issue-1/cover.jpg$gsj$, 'draft', $gsj$Maritime Security Interventions in the Gulf of Guinea$gsj$, $gsj$22 August 2023$gsj$, $gsj$It is clear that maritime security debates over the past few decades have centered on the Gulf of Guinea (GoG) – a region considered the most dangerous for seafarers – and the unique conundrum it presents to maritime security cooperation. The Gulf is characterised by an intricate nexus of threats and governance challenges that have resulted in varied responses from different levels of actors. This volume seeks to collate research on the complexity of maritime security interventions in the Gulf of Guinea, with the ultimate intent of illuminating viable pathways for harmonizing collective efforts towards enhancing shared goals.$gsj$, $gsj$[{"name":"Captain Stephan King","role":"Manager, Capacity Building Maritime Security and Intelligence, Canadian Coast Guard, Government of Canada"},{"name":"Dr Axel Klein","role":"Project Lead, Support to West Africa Integrated Maritime Security (SWAIMS)"},{"name":"Captain António Alexandre","role":"Research and Development Centre of the Portuguese Military University Institute"},{"name":"Dr Alberta Sagoe","role":"Director, Gulf of Guinea Maritime Institute"},{"name":"Stephanie Oserwa Schandorf","role":"Gulf of Guinea Maritime Institute"}]$gsj$::jsonb);

